INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Integration eines Clients die Netzwerkanforderungen untersucht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Netzwerkanforderungen sind essenziell für die Kompatibilität"}, {"text": "Nein", "correct": false, "because": "Untersuchung ist notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es wichtig, die Betriebssystemversion eines Clients vor der Integration zu prüfen?', 2, '[{"text": "Ja", "correct": true, "because": "Kompatibilität mit Netzwerkdiensten hängt davon ab"}, {"text": "Nein", "correct": false, "because": "Version ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Untersuchung der Anforderungen ohne Rücksprache mit dem Benutzer erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Benutzeranforderungen sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Benutzerinput ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Sicherheitsanforderungen bei der Client-Integration berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheit ist ein zentraler Aspekt"}, {"text": "Nein", "correct": false, "because": "Sicherheit ist unerlässlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bandbreitenanforderung eines Clients irrelevant für die Integration?', 2, '[{"text": "Nein", "correct": true, "because": "Bandbreite beeinflusst die Netzwerkleistung"}, {"text": "Ja", "correct": false, "because": "Bandbreite muss untersucht werden"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt sollte zuerst untersucht werden, um die Netzwerkanforderungen eines Clients zu ermitteln?', 2, '[{"text": "Verwendete Anwendungen", "correct": true, "because": "Anwendungen bestimmen Netzwerkbedarf"}, {"text": "Betriebssystem", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Hardwareleistung", "correct": false, "because": "Weniger direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information ist entscheidend, um die Sicherheitsanforderungen eines Clients zu bewerten?', 3, '[{"text": "Zugriffsrechte des Benutzers", "correct": true, "because": "Bestimmt Sicherheitsniveau"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant für Sicherheit"}, {"text": "Prozessorleistung", "correct": false, "because": "Nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll muss untersucht werden, um die IP-Adresszuweisung eines Clients zu gewährleisten?', 2, '[{"text": "DHCP", "correct": true, "because": "DHCP vergibt IP-Adressen dynamisch"}, {"text": "HTTP", "correct": false, "because": "Für Webzugriff, nicht Adresszuweisung"}, {"text": "ICMP", "correct": false, "because": "Für Diagnose, nicht Adressvergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typisches Werkzeug zur Untersuchung der Netzwerkanforderungen eines Clients?', 2, '[{"text": "Netzwerkscanner", "correct": true, "because": "Erkennt Geräte und Dienste"}, {"text": "Texteditor", "correct": false, "because": "Nicht für Netzwerkanalyse"}, {"text": "Grafikprogramm", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Wahl zwischen kabelgebundener und drahtloser Integration?', 2, '[{"text": "Mobilitätsbedarf", "correct": true, "because": "Bestimmt WLAN vs. LAN"}, {"text": "Farbe des Geräts", "correct": false, "because": "Irrelevant"}, {"text": "Betriebszeit", "correct": false, "because": "Weniger entscheidend"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche technischen Anforderungen sollten bei der Client-Integration untersucht werden?', 4, '[{"text": "Betriebssystemkompatibilität", "correct": true, "because": "Muss mit Netzwerkdiensten kompatibel sein"}, {"text": "Netzwerkprotokolle", "correct": true, "because": "z. B. IPv4/IPv6, DHCP"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Nicht netzwerkrelevant"}, {"text": "Bandbreitenbedarf", "correct": true, "because": "Beeinflusst Netzwerkleistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsaspekte müssen bei der Anforderungsuntersuchung berücksichtigt werden?', 3, '[{"text": "Authentifizierungsanforderungen", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Firewall-Regeln", "correct": true, "because": "Regelt Client-Zugriff"}, {"text": "Benutzername des Clients", "correct": true, "because": "Für Zugriffssteuerung"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen sollten vom Benutzer erfragt werden?', 4, '[{"text": "Verwendete Anwendungen", "correct": true, "because": "Bestimmt Netzwerkbedarf"}, {"text": "Erwartete Nutzungszeiten", "correct": true, "because": "Beeinflusst Ressourcenplanung"}, {"text": "Sicherheitsanforderungen", "correct": true, "because": "z. B. Zugriffsbeschränkungen"}, {"text": "Lieblingsfarbe", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkdienste müssen untersucht werden, um die Client-Integration sicherzustellen?', 3, '[{"text": "DHCP", "correct": true, "because": "Für IP-Adressvergabe"}, {"text": "DNS", "correct": true, "because": "Für Namensauflösung"}, {"text": "NTP", "correct": true, "because": "Für Zeitsynchronisation"}, {"text": "SMTP", "correct": false, "because": "Nur für E-Mail"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardwareanforderungen könnten die Integration beeinflussen?', 3, '[{"text": "Netzwerkadapter", "correct": true, "because": "Muss mit Netzwerk kompatibel sein"}, {"text": "RAM-Größe", "correct": true, "because": "Kann Anwendungen beeinflussen"}, {"text": "Prozessorleistung", "correct": true, "because": "Beeinflusst Client-Leistung"}, {"text": "Bildschirmdiagonale", "correct": false, "because": "Nicht netzwerkrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Untersuchung der Anforderungen umfasst Netzwerkprotokolle. b) Die Hardware des Clients ist irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Protokolle ja, Hardware relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sicherheitsanforderungen müssen untersucht werden. b) Benutzeranforderungen können ignoriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, Benutzer nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) DHCP muss für die IP-Adresszuweisung geprüft werden. b) Die Bandbreite ist für die Integration unerheblich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCP ja, Bandbreite relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Untersuchung der Anforderungen hilft bei der Netzwerkplanung. b) Ein Netzwerkscanner ist ein geeignetes Werkzeug dafür.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Planung ja, Scanner hilfreich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Mobilität eines Clients beeinflusst die Integrationsart. b) DNS ist für die Client-Integration unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mobilität ja, DNS relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

